+//************************************************************************
+void ATS_PrintTestStatus(char *testString, boolean passed)
+{
+int	sLen;
+
+	Serial.print(testString);
+	sLen	=	strlen(testString);
+	while (sLen < 60)
+	{
+		Serial.print(' ');
+		sLen++;
+	}
+	Serial_print_P(gTextMsg_dotdotdot);
+	if (passed)
+	{
+		Serial_print_P(gTextMsg_ok);
+	}
+	else
+	{
+		Serial_print_P(gTextMsg_FAIL);
+		gYotalErrors++;
+	}
+	Serial.println();
+	
+	gTestCount++;
+}
