+//************************************************************************
+boolean	ATS_Test_AnalogInput(uint8_t analogPinToTest)
+{
+boolean	passedOK;
+uint8_t helperpin;
+
+	if ((analogPinToTest % 2) == 0)
+	{
+		//*	if its EVEN, add 1
+		helperpin	=	kAnalogPinOffset + analogPinToTest + 1;
+	}
+	else
+	{
+		//*	if its ODD
+		helperpin	=	kAnalogPinOffset + analogPinToTest - 1;
+	}
+	passedOK	=	ATS_Test_AnalogInputWithHelper(analogPinToTest, helperpin);
+	return(passedOK);
+}
