+    * Create variable for the tests. 
+   */
+
+
+  String stringOne;
+  int firstClosingBracket;
+  int firstOpeningBracket;
+  int secondOpeningBracket;
+  int secondClosingBracket;
+  int bodyTag;
+  int firstListItem;
