+	#define	kBoard_AnalogCount	6
+#elif defined(__AVR_ATmega1280__) || defined(__AVR_ATmega2560__)
+	#define	kBoard_PinCount		70
+	#define	kBoard_AnalogCount	16
+#endif
+
