+	for (ii=2; ii<kBoard_PinCount; ii++)
+	{
+		TestTonePin(ii);
+	}
+
+
+	//*	we dont need to test every pin	
+	for (ii=2; ii<kBoard_PinCount; ii += 5)
+	{
+		TestToneDuration(ii);
+	}
+
+
+	ATS_ReportMemoryUsage(startMemoryUsage);
+
+	ATS_end();
+
